                    req._send_json(200, {
                        "data": page2_items,
                        "next_cursor": None,
                        "total_count": 6,
                    })

        config["GET:/payments:*"] = handler

        payments = c.fetch_all_payments()

        assert len(payments) == 6
        assert [p["id"] for p in payments] == [f"p{i}" for i in range(1, 7)]


class TestETagCaching:
    def test_etag_caching(self, client):
        c, config, server, log = client

        items = [make_payment(f"p{i}") for i in range(1, 4)]
        etag_value = '"abc123"'
        call_count = {"n": 0}

        def handler(req):
            call_count["n"] += 1
            if_none_match = req.headers.get("If-None-Match")

            if if_none_match == etag_value:
                req._send_json(304, {})
                return

            req._send_json(200, {
                "data": items,
                "next_cursor": None,
                "total_count": len(items),
            }, {"ETag": etag_value})

        config["GET:/payments:*"] = handler

        first = c.fetch_all_payments()
        second = c.fetch_all_payments()

        assert len(first) == 3
        assert len(second) == 3
        assert first == second
        # Second call should have hit cache via 304
        assert call_count["n"] == 2


