            make_payment("p2", 200, created_at="2024-06-15T09:00:00Z"),        # UTC: 09:00
            make_payment("p3", 300, created_at="2024-06-15T04:00:00-05:00"),   # UTC: 09:00
            make_payment("p4", 400, created_at="2024-06-15T11:00:00Z"),        # UTC: 11:00
